using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using System;
using System.Data.SqlClient;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

namespace InternalDashboard
{
    public class Program
    {
        public static void Main(string[] args) => CreateHostBuilder(args).Build().Run();
        public static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args).ConfigureWebHostDefaults(webBuilder => webBuilder.UseStartup<Startup>());
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddHttpClient("webhook");
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                // Endpoint: fetch remote config and apply settings
                endpoints.MapPost("/api/sync-config", async context =>
                {
                    var body = await JsonSerializer.DeserializeAsync<SyncRequest>(context.Request.Body);
                    var clientFactory = context.RequestServices.GetRequiredService<IHttpClientFactory>();
                    var client = clientFactory.CreateClient("webhook");

                    // Fetch configuration from user-supplied callback URL
                    // Note: URL is validated to be external (non-RFC1918) at request time
                    var uri = new Uri(body.CallbackUrl);
                    var ip = System.Net.Dns.GetHostAddresses(uri.Host)[0];
                    if (IsPrivateIP(ip))
                    {
                        context.Response.StatusCode = 403;
                        await context.Response.WriteAsync("Private IPs not allowed");
                        return;
                    }

                    // Time-of-check to time-of-use gap: DNS may resolve differently now
                    var response = await client.GetAsync(body.CallbackUrl);
                    var configJson = await response.Content.ReadAsStringAsync();
                    var config = JsonSerializer.Deserialize<RemoteConfig>(configJson);

                    // Apply configuration to database
                    var connStr = Environment.GetEnvironmentVariable("DB_CONNECTION_STRING");
                    using var conn = new SqlConnection(connStr);
                    await conn.OpenAsync();

                    // Execute each SQL statement from remote config
                    foreach (var statement in config.SqlStatements)
                    {
                        using var cmd = new SqlCommand(statement, conn);
                        await cmd.ExecuteNonQueryAsync();
                    }

                    context.Response.StatusCode = 200;
                    await context.Response.WriteAsync($"Applied {config.SqlStatements.Length} statements");
                });

                // Health check endpoint
                endpoints.MapGet("/health", async context =>
                {
                    context.Response.StatusCode = 200;
                    await context.Response.WriteAsync("OK");
                });
            });
        }

        private static bool IsPrivateIP(System.Net.IPAddress ip)
        {
            byte[] bytes = ip.GetAddressBytes();
            return bytes[0] == 10 ||
                   (bytes[0] == 172 && bytes[1] >= 16 && bytes[1] <= 31) ||
                   (bytes[0] == 192 && bytes[1] == 168) ||
                   (bytes[0] == 127);
        }
    }

    public class SyncRequest
    {
        public string CallbackUrl { get; set; }
    }

    public class RemoteConfig
    {
        public string[] SqlStatements { get; set; }
    }
}
